        postJson("/api/schedules", scheduleBody(key("sc"), key("sk"), allocationKey,
                "2027-02-01T02:00:00Z", "2027-02-01T01:00:00Z"), null, 400);
        // 超出窗口范围
        postJson("/api/schedules", scheduleBody(key("sc"), key("sk"), allocationKey,
                "2027-01-31T23:30:00Z", "2027-02-01T00:30:00Z"), null, 400);
        postJson("/api/schedules", scheduleBody(key("sc"), key("sk"), allocationKey,
